 "content": "from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            if len(comp) == 1:
                y, x = comp[0]
                around = [grid[yy][xx] for dy, dx in ((1,0),(-1,0),(0,1),(0,-1))
                          if 0 <= (yy := y + dy) < h and 0 <= (xx := x + dx) < w]
                counts = Counter(around)
                if counts:
                    out[y][x] = counts.most_common(1)[0][0]
    return out
